class BenchmarkLeakageError(RuntimeError):
    """Raised when an audited transcript accesses forbidden benchmark or cross-arm files."""

    exit_code: int = 2


def _rmtree_onexc(func: Any, path: str, _exc: BaseException) -> None:
    try:
        os.chmod(path, stat.S_IWRITE)
        func(path)
    except OSError:
        pass


def safe_rmtree(path: str | Path) -> None:
    """Remove a directory tree cleanly on Windows (handling read-only .git pack files)."""
    target = Path(path)
    if target.exists():
        shutil.rmtree(target, onexc=_rmtree_onexc)


def _decode_z64_text(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob.encode("ascii"))).decode("utf-8")


def _decode_z64_dict(blob: str) -> dict[str, str]:
    raw = zlib.decompress(base64.b64decode(blob.encode("ascii"))).decode("utf-8")
    data = json.loads(raw)
    if not isinstance(data, dict):
        raise ValueError("Decoded blob is not a dict")
    return {str(k): str(v) for k, v in data.items()}


